class Solution {
public:
    int countGoodSubsequences(string s) {
        const long long MOD = 1000000007;
        int n = s.size();
        vector<int> freq(26);
        for (char c : s) ++freq[c - 'a'];
        vector<long long> fact(n + 1, 1), inv(n + 1, 1);
        auto power = [&](long long a, long long b) {
            long long r = 1;
            while (b) {
                if (b & 1) r = r * a % MOD;
                a = a * a % MOD;
                b >>= 1;
            }
            return r;
        };
        for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % MOD;
        inv[n] = power(fact[n], MOD - 2);
        for (int i = n; i > 0; --i) inv[i - 1] = inv[i] * i % MOD;
        long long answer = 0;
        for (int k = 1; k <= *max_element(freq.begin(), freq.end()); ++k) {
            long long ways = 1;
            for (int f : freq) if (f >= k) {
                long long choose = fact[f] * inv[k] % MOD * inv[f - k] % MOD;
                ways = ways * (choose + 1) % MOD;
            }
            answer = (answer + ways - 1 + MOD) % MOD;
        }
        return (int)answer;
    }
};
